layers.vertex:
attribute vec3 aO; attribute float aT, aK; uniform float uTime; varying vec2 vP; varying float vU, vK;
    void main(){ float u = uTime - aT; if (u < 0. || u > 1.8){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec3 f = cameraPosition - aO; f.y = 0.; f = normalize(f); vec3 rt = vec3(f.z, 0., -f.x);
      vP = vec2(position.x*.9, (position.y*.5 + .5)*3.4); vU = u; vK = aK;
      gl_Position = projectionMatrix*viewMatrix*vec4(aO + rt*vP.x + vec3(0., vP.y, 0.), 1.); }

layers.fragment:
uniform float uTime; uniform vec3 uV, uBl, uW; varying vec2 vP; varying float vU, vK; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); } float h1(float n){ return fract(sin(n*91.7)*43758.5); }
    float edgeAt(float t, float k){ float e = clamp(t/0.68, 0., 1.); return k < .5 ? 2. - 2.05*e*e : 2.05*(1. - (1. - e)*(1. - e)) - .05; }
    float star(vec2 q, float sz){ float r = length(q), a = atan(q.y, q.x); return pow(abs(cos(a*2.)), 12.)*exp(-r/sz*1.4) + exp(-r*r/(sz*sz*.08)); }
    void main(){
      float x = vP.x, y = vP.y, lum = 0., hot = 0.;
      float tb = vK < .5 ? vU : vU - 0.38;                                  /* time of the body sweep */
      float edge = edgeAt(tb, vK), sweep = tb >= 0. && tb < 0.68 ? 1. : (tb >= 0.68 ? exp(-(tb - 0.68)*9.) : 0.);
      lum += exp(-pow((y - edge)/.18, 2.))*exp(-x*x/.1)*.5*sweep;                    /* soft glow where the body dissolves / forms */
      for (int i=0;i<22;i++){
        float fi = float(i), a1 = h1(fi), a2 = h1(fi + 5.), a3 = h1(fi + 11.), a4 = h1(fi + 17.);
        float ts = a1*0.68, sz = .05 + .04*a4, x0 = (a2 - .5)*.7;
        vec2 P; float life;
        if (vK < .5){ float t = vU - ts; if (t < 0. || t > .9) continue;              /* leaves the edge, drifts up and away */
          P = vec2(x0*(1. + t*1.6) + (a3 - .5)*.4*t, edgeAt(ts, 0.) + t*(.6 + .8*a3) + t*t*.9); life = sin(3.14159*pow(t/.9, .7)); }
        else { float t = tb - ts + .525; if (t < 0. || t > .71) continue;               /* falls from above, gathers onto the edge */
          float k = clamp(t/.525, 0., 1.), yE = edgeAt(ts, 1.);
          P = vec2(x0*mix(2.2, .7, k*k), mix(yE + 1.3 + a3, yE, 1. - (1. - k)*(1. - k))); life = t < .525 ? pow(k, .6) : 1. - (t - .525)/.19; }
        float tw = .6 + .4*sin(vU*26. + fi*2.3);
        float s = star(vec2(x, y) - P, sz)*tw*life;
        lum += s; hot += exp(-dot(vec2(x, y) - P, vec2(x, y) - P)/(sz*sz*.03))*tw*life;
      }
      if (vK > .5){ float c = tb - 0.68; if (c >= 0. && c < .375){                     /* re-formed: one soft 4-point star on the chest */
        vec2 q = vec2(x, y - 1.3); float qa = atan(q.y, q.x), qr = length(q), ff = pow(1. - c/.375, 1.5);
        lum += (pow(abs(cos(qa*2.)), 22.)*exp(-qr*3.5) + exp(-qr*qr*60.)*.6)*ff; hot += exp(-qr*qr*300.)*ff; } }
      float m = smoothstep(.9, .7, abs(x))*smoothstep(3.4, 3., y);
      vec3 o = (uBl*lum*.8 + uV*lum*.35 + uW*hot*.9)*m;
      o = max(o, 0.); if (!(max(o.r, max(o.g, o.b)) >= .002)) discard; gl_FragColor = vec4(o, 1.); }

layers.vertex:
attribute vec3 aO; attribute float aT; uniform float uTime; varying vec2 vP; varying float vU;
    void main(){
      float u = uTime - aT; if (u < 0. || u > 0.45){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float S = .5; vP = position.xy*.9; vU = u;                  // only the immediate base of the feet
      gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .03, -position.y*S), 1.);
    }

layers.fragment:
uniform vec3 uCy, uBu; varying vec2 vP; varying float vU; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); } float h1(float n){ return fract(sin(n*91.7)*43758.5); }
    float seg(vec2 p, vec2 a, vec2 b){ vec2 pa = p-a, ba = b-a; float h = clamp(dot(pa,ba)/dot(ba,ba), 0., 1.); return length(pa - ba*h); }
    void main(){
      vec2 p = vP; float r = length(p);
      float k = 1. - pow(1. - clamp(vU/.06, 0., 1.), 3.);               // snaps shut in 60 ms
      float R = mix(.75, .42, k);
      float ring = 0., hot = 0.;                                        // no circle: only the stakes at the ankles (ground space is for areas)
      float st = 0.;
      for (int j=0;j<4;j++){
        float an = .7854 + float(j)*1.5708; vec2 d = vec2(cos(an), sin(an));
        float ds = seg(p, d*(R - .17), d*(R + .03));
        st += exp(-pow(ds/.014, 2.)); hot += lcore(ds, .004);
      }
      float f = vU < .06 ? 1. : 1. - smoothstep(.2, 0.45, vU);
      float pk = vU >= .06 && vU < .093 ? 1.6 : 1.;                    // 2-frame peak when it locks
      float edge = smoothstep(.9, .78, r);
      vec3 outc = (mix(uBu, uCy, .6)*(ring*.9 + st*.8) + vec3(1., .95, .86)*hot*.6)*f*pk*edge;
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }
